import { useState } from "react";
import axios from "axios";
import "./App.css";

export default function App() {
  const [screen, setScreen] = useState("login");
  const [token, setToken] = useState(null);
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [walletAddress, setWalletAddress] = useState(null);
  
  // Content Generation
  const [prompt, setPrompt] = useState("");
  const [generatedContent, setGeneratedContent] = useState("");
  const [taskId, setTaskId] = useState("");
  const [payment, setPayment] = useState(null);
  const [loading, setLoading] = useState(false);
  const [tasks, setTasks] = useState([]);
  const [attestations, setAttestations] = useState([]);

  // Product search
  const [productQuery, setProductQuery] = useState("");
  const [productBudget, setProductBudget] = useState("");
  const [productResults, setProductResults] = useState(null);
  const [searchingProduct, setSearchingProduct] = useState(false);
  const [confirmingPayment, setConfirmingPayment] = useState(false);
  const [confirmPaymentResult, setConfirmPaymentResult] = useState(null);
  
  // Kite health
  const [kiteStatus, setKiteStatus] = useState(null);
  const [settlements, setSettlements] = useState([]);
  const [remainingBudget, setRemainingBudget] = useState(null);

  const API_BASE = process.env.REACT_APP_API_URL || "http://localhost:8001";
  const headers = token ? { Authorization: `Bearer ${token}` } : {};

  const handleRegister = async () => {
    try {
      const res = await axios.post(`${API_BASE}/register`, { username, password });
      setToken(res.data.token);
      setScreen("generate");
      setUsername("");
      setPassword("");
    } catch (e) {
      alert(`Registration failed: ${e.response?.data?.detail || e.message}`);
    }
  };

  const handleLogin = async () => {
    try {
      const res = await axios.post(`${API_BASE}/login`, { username, password });
      setToken(res.data.token);
      setScreen("generate");
      setUsername("");
      setPassword("");
      checkKiteHealth();
      await loadUserTasks();
      await loadKiteAttestations();
      await loadKiteSettlements();
    } catch (e) {
      alert(`Login failed: ${e.response?.data?.detail || e.message}`);
    }
  };

  const checkKiteHealth = async () => {
    try {
      const res = await axios.get(`${API_BASE}/kite/health`);
      setKiteStatus(res.data);
    } catch (e) {
      console.error("Kite health check failed:", e);
    }
  };

  const handleGenerate = async (retries = 0) => {
    if (!prompt.trim()) {
      alert("Enter a prompt");
      return;
    }

    setLoading(true);
    try {
      const res = await axios.post(
        `${API_BASE}/generate`,
        { prompt },
        { headers }
      );
      setGeneratedContent(res.data.generated_content);
      setTaskId(res.data.task_id);
      setPayment(res.data);
      setScreen("confirm");
    } catch (e) {
      const error = e.response?.data?.detail || e.message;
      if (error.includes("429") && retries < 3) {
        alert(`Rate limited. Retrying in 3 seconds... (attempt ${retries + 1}/3)`);
        setTimeout(() => handleGenerate(retries + 1), 3000);
      } else {
        alert(`Generation failed: ${error}`);
      }
    } finally {
      setLoading(false);
    }
  };

  const handleConfirmGeneration = async () => {
    setLoading(true);
    try {
      await axios.post(
        `${API_BASE}/confirm-generation`,
        {
          task_id: taskId,
          payment_amount_usdc: payment.payment_amount_usdc,
          vendor_address: "0x742d35Cc6634C0532925a3b844Bc89e7595f42A"
        },
        { headers }
      );
      
      alert("✅ Content generated and payment settled on Kite AI!");
      
      setGeneratedContent("");
      setTaskId("");
      setPayment(null);
      setPrompt("");
      
      await loadUserTasks();
      setScreen("generate");
    } catch (e) {
      alert(`Confirmation failed: ${e.response?.data?.detail || e.message}`);
    } finally {
      setLoading(false);
    }
  };

  const loadUserTasks = async () => {
    try {
      const res = await axios.get(`${API_BASE}/tasks`, { headers });
      setTasks(res.data.tasks);
      setAttestations(res.data.attestations);
    } catch (e) {
      console.error("Failed to load tasks:", e);
    }
  };

  const loadKiteAttestations = async () => {
    try {
      const res = await axios.get(`${API_BASE}/kite/attestations/${username}`, { headers });
      setAttestations(res.data.attestations || []);
    } catch (e) {
      console.error("Failed to load kite attestations:", e);
    }
  };

  const loadKiteSettlements = async () => {
    try {
      const res = await axios.get(`${API_BASE}/kite/settlements`, { headers });
      setSettlements(res.data.settlements || []);
    } catch (e) {
      console.error("Failed to load kite settlements:", e);
    }
  };

  const handleProductSearch = async () => {
    if (!productQuery.trim() || !productBudget || Number(productBudget) <= 0) {
      alert("Enter product and budget");
      return;
    }

    setSearchingProduct(true);
    setProductResults(null);
    setConfirmPaymentResult(null);
    setRemainingBudget(Number(productBudget));

    try {
      const res = await axios.post(
        `${API_BASE}/buy`,
        {
          query: productQuery,
          budget: Number(productBudget),
          search_online: true
        },
        { headers }
      );

      setProductResults(res.data);
      if (res.data.status === "payment_required") {
        const used = Number(res.data.product?.price || 0);
        setRemainingBudget(Number(productBudget) - used);
      }
    } catch (e) {
      // Handle 402 (Payment Required) as success
      if (e.response?.status === 402) {
        setProductResults(e.response.data);
        const used = Number(e.response.data.product?.price || 0);
        setRemainingBudget(Number(productBudget) - used);
      } else {
        const error = e.response?.data || e.message;
        setProductResults({ status: "error", error });
      }
    } finally {
      setSearchingProduct(false);
    }
  };

  const connectWallet = async () => {
    if (!window.ethereum) {
      alert("MetaMask not detected. Please install MetaMask.");
      return;
    }

    try {
      const accounts = await window.ethereum.request({ method: "eth_requestAccounts" });
      setWalletAddress(accounts[0]);
      return accounts[0];
    } catch (e) {
      console.error("Wallet connect failed", e);
      alert("Wallet connection failed: " + e.message);
      return null;
    }
  };

  const handleConfirmProductPayment = async () => {
    if (!productResults || productResults.status !== "payment_required") {
      alert("No payable product selected");
      return;
    }

    let address = walletAddress;
    if (!address) {
      address = await connectWallet();
      if (!address) return;
    }

    const product = productResults.product;
    const vendorAddress = productResults.vendor_address || productResults.product?.vendor_address || productResults.product?.url;
    if (!vendorAddress) {
      alert("No vendor address in payment payload");
      return;
    }

    const paymentPayload = {
      product_name: product.name,
      price: product.price,
      currency: product.currency,
      vendor_address: vendorAddress
    };

    const message = `Autobuy payment confirmation ${JSON.stringify(paymentPayload, Object.keys(paymentPayload).sort())}`;

    try {
      const signature = await window.ethereum.request({
        method: "personal_sign",
        params: [message, address]
      });

      setConfirmingPayment(true);
      setConfirmPaymentResult(null);

      const response = await axios.post(
        `${API_BASE}/confirm-payment`,
        {
          product,
          vendor_address: vendorAddress,
          wallet_address: address,
          signature
        },
        { headers }
      );

      setConfirmPaymentResult({ status: "success", data: response.data });
      await loadKiteAttestations();
      await loadKiteSettlements();
    } catch (e) {
      setConfirmPaymentResult({ status: "error", error: e.response?.data || e.message });
    } finally {
      setConfirmingPayment(false);
    }
  };

  const handleLogout = () => {
    setToken(null);
    setScreen("login");
    setTasks([]);
    setAttestations([]);
  };

  return (
    <div className="App">
      <header className="header">
        <h1>🤖 Kite AI Content Generation Agent</h1>
        {token && <button onClick={handleLogout} className="logout-btn">Logout</button>}
      </header>

      {/* Login / Register */}
      {screen === "login" && (
        <div className="auth-container">
          <div className="auth-box">
            <h2>Get Started</h2>
            <input
              type="text"
              placeholder="Username"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
            />
            <input
              type="password"
              placeholder="Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
            <button onClick={handleLogin}>Login</button>
            <button onClick={handleRegister} className="secondary">
              Register
            </button>
          </div>
        </div>
      )}

      {/* Content Generation */}
      {screen === "generate" && token && (
        <div className="container">
          <div className="kite-status">
            {kiteStatus && (
              <p>
                🔗 Kite: <strong>{kiteStatus.status}</strong> on{" "}
                {kiteStatus.network}
              </p>
            )}
          </div>

          <div className="generator-box">
            <h2>Generate Content</h2>
            <textarea
              placeholder="Enter prompt (e.g., Write a blog post about AI)"
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              rows="4"
            />
            <button onClick={handleGenerate} disabled={loading}>
              {loading ? "Generating..." : "Generate Content"}
            </button>
          </div>

          <div className="product-search-box">
            <h2>Find Product Online</h2>
            <div style={{marginBottom: '10px'}}>
              {walletAddress ? (
                <p>Wallet connected: <strong>{walletAddress}</strong></p>
              ) : (
                <button onClick={connectWallet} style={{marginBottom:'10px'}}>
                  Connect Wallet (MetaMask)
                </button>
              )}
            </div>
            <input
              type="text"
              placeholder="e.g. laptop $500 to $600"
              value={productQuery}
              onChange={(e) => setProductQuery(e.target.value)}
            />
            <input
              type="number"
              placeholder="Budget (USD)"
              value={productBudget}
              onChange={(e) => setProductBudget(e.target.value)}
            />
            <button onClick={handleProductSearch} disabled={searchingProduct}>
              {searchingProduct ? "Searching..." : "Search Product"}
            </button>

            {productResults && (
              <div className="product-results">
                {productResults.status === "error" ? (
                  <p className="error">Error: {JSON.stringify(productResults.error)}</p>
                ) : productResults.status === "payment_required" ? (
                  <>
                    <h3>Best Match</h3>
                    <p>{productResults.product.name}</p>
                    <p>Price: ${productResults.product.price.toFixed(2)}</p>
                    <p>Source: {productResults.product.store || productResults.product.source}</p>
                    <p>Remaining budget: ${remainingBudget != null ? remainingBudget.toFixed(2) : 'N/A'}</p>
                    <p>In-range: {productResults.product.price <= Number(productBudget) ? 'yes' : 'no'}</p>
                    <p>Not sponsor: {(!productResults.product.name.toLowerCase().includes('ad based') && !productResults.product.name.toLowerCase().includes('sponsored')) ? 'yes' : 'no'}</p>
                    <a href={productResults.product.url} target="_blank" rel="noreferrer">Open product link</a>

                    <h4>Top Results</h4>
                    <ul>
                      {productResults.search_results?.map((item, idx) => (
                        <li key={idx}>
                          <strong>{item.name}</strong> - ${item.price.toFixed(2)} - {item.store}
                          {item.url && ( <><br/><a href={item.url} target="_blank" rel="noreferrer">Read details</a></> )}
                        </li>
                      ))}
                    </ul>

                    <div className="payment-confirmation">
                      <button onClick={handleConfirmProductPayment} disabled={confirmingPayment}>
                        {confirmingPayment ? "Confirming payment..." : "Confirm payment (USDC / x402)"}
                      </button>

                      {confirmPaymentResult && confirmPaymentResult.status === "success" && (
                        <div className="success">
                          <h5>Payment settled on Kite</h5>
                          <p>Tx Hash: {confirmPaymentResult.data.tx_hash}</p>
                          <p>Status: {confirmPaymentResult.data.payment_status}</p>
                        </div>
                      )}

                      {confirmPaymentResult && confirmPaymentResult.status === "error" && (
                        <div className="error">Error: {JSON.stringify(confirmPaymentResult.error)}</div>
                      )}
                    </div>
                  </>
                ) : (
                  <p>No matching product found within budget.</p>
                )}
              </div>
            )}
          </div>

          {/* Task History */}
          {tasks.length > 0 && (
            <div className="history-box">
              <h3>Your Tasks ({tasks.length})</h3>
              <div className="task-list">
                {tasks.map((task) => (
                  <div key={task.task_id} className="task-item">
                    <small>ID: {task.task_id.substring(0, 20)}...</small>
                    <p>Prompt: {task.prompt.substring(0, 50)}...</p>
                    <p className="content-preview">Content: {task.generated_content.substring(0, 80)}...</p>
                    <small>Tokens: {task.tokens_used}</small>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Attestations on Kite */}
          {attestations.length > 0 && (
            <div className="attestations-box">
              <h3>Kite Attestations ({attestations.length})</h3>
              <div className="attestation-list">
                {attestations.map((att) => (
                  <div key={att.task_id} className="attestation-item">
                    <p>✅ Task: {att.task_id.substring(0, 20)}...</p>
                    <p>Hash: {att.output_hash.substring(0, 20)}...</p>
                    <p>Status: <strong>{att.status}</strong></p>
                    <small>{new Date(att.timestamp).toLocaleString()}</small>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Settlements on Kite */}
          {settlements.length > 0 && (
            <div className="settlements-box">
              <h3>Kite Settlements ({settlements.length})</h3>
              <div className="settlement-list">
                {settlements.map((s) => (
                  <div key={s.settlement_id} className="settlement-item">
                    <p>🧾 ID: {s.settlement_id}</p>
                    <p>Amount: ${s.amount}</p>
                    <p>Tx: {s.tx_hash.substring(0, 20)}...</p>
                    <p>Status: <strong>{s.status}</strong></p>
                    <small>{new Date(s.settled_at).toLocaleString()}</small>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {/* Confirm Generation */}
      {screen === "confirm" && payment && (
        <div className="container">
          <div className="confirm-box">
            <h2>✨ Content Generated!</h2>
            
            <div className="content-display">
              <h3>Generated Content:</h3>
              <p>{generatedContent}</p>
            </div>

            <div className="details">
              <p>
                <strong>Output Hash:</strong>{" "}
                <code>{payment.output_hash.substring(0, 30)}...</code>
              </p>
              <p>
                <strong>Tokens Used:</strong> {payment.tokens_used}
              </p>
              <p>
                <strong>Model:</strong> {payment.model}
              </p>
            </div>

            <div className="payment-box">
              <h3>⚙️ Settle Payment on Kite</h3>
              <p>
                Amount: <strong>${payment.payment_amount_usdc.toFixed(2)} USDC</strong>
              </p>
              <p className="kite-note">
                🔗 Payment will be settled on Kite AI Chain with attestation proof
              </p>
              <button
                onClick={handleConfirmGeneration}
                disabled={loading}
                className="confirm-btn"
              >
                {loading ? "Settling..." : "Confirm & Settle on Kite"}
              </button>
              <button
                onClick={() => setScreen("generate")}
                className="secondary"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
